import Link from "next/link";
import { HomeArt } from "./HomeArt";
import { HouseSlideshow } from "./HouseSlideshow";
import { SectionRenderer } from "@/components/sections/SectionRenderer";
import { VideoPlayer } from "@/components/sections/VideoPlayer";
import { ProductCard } from "@/components/ProductCard";
import { catalogue } from "@/lib/data/catalogue";
import { sortProducts } from "@/lib/facets/engine";
import type { SiteText } from "@/lib/content/site-text-defs";
import type { Section } from "@/lib/content/sections";
import styles from "./Homepage.module.css";

function Arrow() { return <span aria-hidden="true">↗</span>; }

export async function HomepageSection({ section, index, text }: { section: Section; index: number; text: SiteText }) {
  switch (section.type) {
    case "heroCarousel": return <HouseSlideshow slides={section.slides} variant="hero" />;
    case "brandStatement": return <section className={styles.statement}>
      <span className={styles.kicker}>{text["home.statement.eyebrow"]}</span>
      <h2>{section.quote}</h2>
      <div className={styles.statementFoot}><span className={styles.lotus} aria-hidden="true">✧</span><p className={styles.body}>{section.body}</p><Link href="/pages/our-story" className={styles.textLink}>{text["home.statement.link"]}<Arrow /></Link></div>
    </section>;
    case "categorySplit": return <section className={styles.categories}>
      <div className={styles.sectionHeading}><div><span className={styles.kicker}>{text["home.category.eyebrow"]}</span><h2>{text["home.category.heading"]}</h2></div><Link href="/collections/all" className={styles.textLink}>{text["home.category.link"]}<Arrow /></Link></div>
      <div className={styles.categoryGrid}>{section.items.map((item, i) => <Link key={`${item.href}-${i}`} href={item.href} className={styles.categoryCard}>
        <HomeArt art={item.art} alt={item.label} sizes="(min-width: 768px) 50vw, 100vw" />
        <div className={styles.categoryCaption}><span className={styles.kicker}>{String(i + 1).padStart(2, "0")} / THE WARDROBE</span><h3>{item.label}</h3><span className={styles.roundArrow} aria-hidden="true">↗</span></div>
      </Link>)}</div>
    </section>;
    case "collectionTriptych": return <section className={styles.triptych}>
      <div className={styles.triptychIntro}><span className={styles.kicker}>{text["home.triptych.eyebrow"]}</span><h2>{section.title}</h2><p className={styles.body}>{section.body}</p><Link href={section.ctaHref} className={styles.textLink}>{section.ctaLabel}<Arrow /></Link></div>
      <div className={styles.triptychImages}>{section.art.map((art, i) => <Link key={i} href={section.artHrefs?.[i] || section.ctaHref} className={styles.triptychPhoto} aria-label={`Explore ${section.title}, piece ${i + 1}`}>
        <HomeArt art={art} alt={`${section.title}, piece ${i + 1}`} sizes="(min-width: 1024px) 25vw, (min-width: 768px) 33vw, 75vw" /><span className={styles.photoNumber}>0{i + 1}<Arrow /></span>
      </Link>)}</div>
    </section>;
    case "videoBand": return <section className={styles.craft}>
      <div className={styles.craftCopy}><span className={styles.kicker}>{text["home.craft.eyebrow"]}</span><h2>{section.title}</h2><p className={styles.body}>{section.body}</p><Link href={section.ctaHref} className={styles.textLink}>{section.ctaLabel}<Arrow /></Link><span className={styles.craftNote}>{text["home.craft.note"].toUpperCase()}</span></div>
      <div className={styles.craftFilm}>{section.videoSrc ? <VideoPlayer src={section.videoSrc} poster={section.art.desktop.src} className={styles.video} /> : <HomeArt art={section.art} alt={section.title} />}</div>
    </section>;
    case "tileRow": return <section className={styles.edits}>
      <div className={styles.sectionHeading}><div><span className={styles.kicker}>{text["home.edits.eyebrow"]}</span><h2>{text["home.edits.heading"]}</h2></div><span className={styles.sectionAside}>{text["home.edits.note"].toUpperCase()}</span></div>
      <div className={styles.editGrid}>{section.items.map((item, i) => <Link key={`${item.href}-${i}`} href={item.href} className={styles.editCard}>
        <HomeArt art={item.art} alt={item.label} sizes="(min-width: 768px) 25vw, 50vw" />
        <div><span className={styles.kicker}>EDIT / {String(i + 1).padStart(2, "0")}</span><h3>{item.label}<Arrow /></h3></div>
      </Link>)}</div>
    </section>;
    case "campaignSlideshow": return <HouseSlideshow slides={section.slides} variant="story" />;
    case "editorialSlideshow": return <HouseSlideshow slides={section.slides} variant="wardrobe" />;
    case "storesSlideshow": return <HouseSlideshow slides={section.slides} variant="stores" />;
    case "richText": return <section className={styles.closing}><span className={styles.kicker}>{text["home.closing.eyebrow"]}</span>{section.heading && <h2>{section.heading}</h2>}{section.paragraphs.map((paragraph, i) => <p className={styles.body} key={i}>{paragraph}</p>)}{section.ctaHref && <Link href={section.ctaHref} className={styles.textLink}>{section.ctaLabel}<Arrow /></Link>}</section>;
    case "productRail": {
      const collection = await catalogue.getCollection(section.collectionHandle);
      if (!collection) return null;
      const products = sortProducts(await catalogue.productsInCollection(collection), "featured").slice(0, 4);
      return <section className={styles.products}><div className={styles.sectionHeading}><div><span className={styles.kicker}>{text["home.products.eyebrow"]}</span><h2>{section.title}</h2></div><Link href={`/collections/${section.collectionHandle}`} className={styles.textLink}>{section.ctaLabel}<Arrow /></Link></div>
        <ul className={styles.productGrid}>{products.map((product) => <li key={product.handle}><ProductCard product={product} quickView sizes="(min-width: 768px) 25vw, 50vw" /><p className={styles.productDetail}>{product.provenance.workshop}</p></li>)}</ul>
      </section>;
    }
    default: return <SectionRenderer section={section} index={Math.max(1, index)} />;
  }
}
