import Image from "next/image";
import type { ArtPair } from "@/lib/content/sections";
import { toneFor } from "@/components/Frame";
import styles from "./Homepage.module.css";

export function HomeArt({ art, alt, priority = false, sizes = "(min-width: 1024px) 60vw, 100vw", className = "" }: {
  art: ArtPair; alt: string; priority?: boolean; sizes?: string; className?: string;
}) {
  const differentCrop = Boolean(art.mobile?.src && art.mobile.src !== art.desktop.src);
  return <div className={`${styles.art} ${className}`} style={{ backgroundColor: toneFor(art.desktop.tone) }}>
    {art.desktop.src && <Image src={art.desktop.src} alt={alt} fill sizes={sizes}
      preload={priority && !differentCrop} className={differentCrop ? styles.desktopImage : undefined} />}
    {differentCrop && art.mobile?.src && <Image src={art.mobile.src} alt={alt} fill sizes="100vw" className={styles.mobileImage} />}
  </div>;
}
