import { HomepageSection } from "@/components/homepage/HomepageSection";
import { content } from "@/lib/content/content";
import { BRAND } from "@/lib/brand";
import { getSiteText } from "@/lib/content/site-text";
import styles from "@/components/homepage/Homepage.module.css";

export const revalidate = 60;

export default async function HomePage() {
  const [sections, text] = await Promise.all([content.getHomepageSections(), getSiteText()]);
  return <div className={styles.home}>
    <h1 className="sr-only">{BRAND.name} — handwoven Banarasi textiles</h1>
    {sections.map((section, index) => <div key={section.id} id={section.id} data-home-section={section.type}>
      <HomepageSection section={section} index={index} text={text} />
    </div>)}
  </div>;
}
